/*
 * VTOCE_$TRUNCATE - truncate or delete a local object's file map
 *
 * Original address: 0x00E39E42 (SAU2 map: VTOC_, VTOCE_$TRUNCATE at E39E42)
 * Size: 1234 bytes (0x00E39E42 .. 0x00E3A313)
 * Nested:  vtoc_$free_indirect, 0x00E39BC2 .. 0x00E39E41 (640 bytes; not
 *          in the map, a module-local Pascal procedure nested in this one:
 *          it is entered with the caller's A6 in A1 as its static link)
 *
 * Generated by: Claude Opus 5.5
 *
 * Under ML lock 0x10, on a mounted volume:
 *   - delete on a new-format volume: the UID is hashed and the bucket
 *     chain walked until the slot holding the UID is found (the bucket
 *     block stays held for later);
 *   - the VTOCE block is fetched.  A new-format entry must be in use and
 *     carry the UID, an old-format one is taken as is;
 *   - delete: the entry's in-use bit is cleared (new format: the block's
 *     entry count drops and, at 2, BAT_$ADD_PART_VTOCE relinks the block)
 *     and the UID-cache entry is dropped.  Truncate: an indirect root
 *     whose whole range lies at or beyond the new end is zeroed;
 *   - every direct block at or beyond the new end is collected into
 *     vtoc_$data.free_list and zeroed;
 *   - a changed VTOCE is written back (0xB), the collected blocks freed
 *     and the bucket slot cleared; an unchanged one is released with 9;
 *   - the three indirect trees are walked by vtoc_$free_indirect.
 *
 * Frame (link.w A6,-0x5c; D2-D7/A2-A5 saved; A5 = 0xE784D0 = &vtoc_$data):
 *   (0x08,A6)  loc           object location record
 *   (0x0C,A6)  size          never read
 *   (0x10,A6)  alloc_length  byte length -> blocks at (-0x34,A6)
 *   (0x14,A6)  delete_it     BOOLEAN byte in a word slot
 *   (0x16,A6)  blocks_freed  pointer
 *   (0x1A,A6)  status        pointer
 *   (-0x04,A6) cache_info    UID-cache block_info out (ignored)
 *   (-0x08,A6) direct        pointer to the entry's 32 direct addresses
 *   (-0x1C,A6) scratch       status of the "clean" releases
 *   (-0x20,A6) bkt_buf       the held bucket block, or NULL
 *   (-0x2C,A6) vtoce_block   loc->block_hint >> 4
 *   (-0x30,A6) bkt_block     hash result, then D2 walks the chain
 *   (-0x34,A6) new_blocks    ceil(alloc_length / 1024)
 *   (-0x36,A6) vol_idx       the byte loc+0x1C, zero-extended
 *   (-0x38,A6) cache_flags   UID-cache flags out (ignored)
 *   (-0x3C,A6) bkt_idx       bucket index within bkt_block
 *   (-0x3E,A6) i             direct-loop start (stored once)
 *   (-0x40,A6) freed         direct blocks collected
 *   (-0x48,A6) found         bucket slot found
 *   (-0x4A,A6) changed       VTOCE modified
 *   D3b entry index (loc byte +7 & 0xF); D4b format flag of the volume;
 *   D7w bucket slot index; D2/D5/D6 the three indirect roots; A2 the VTOCE
 *   block; A1 the entry's three roots.
 */

#include "vtoc/vtoc_internal.h"
#include "math/math.h"

/*
 * The enclosing-scope cells vtoc_$free_indirect reaches through its static
 * link A4 (the caller's A6).  This is a C flattening of the Pascal frame,
 * not an image record, so it carries no layout asserts.
 */
typedef struct vtoce_$truncate_frame_t {
    vtoc_$lookup_req_t  *loc;           /* (0x08,A4): +0x08 is the UID */
    uint32_t            *blocks_freed;  /* (0x16,A4) */
    status_$t           *status;        /* (0x1A,A4) */
    status_$t           scratch;        /* (-0x1C,A4) */
    uint32_t            new_blocks;     /* (-0x34,A4) */
    uint16_t            vol_idx;        /* (-0x36,A4) */
} vtoce_$truncate_frame_t;

/*
 * vtoc_$free_indirect - free the part of an indirect tree beyond new_blocks
 *
 * 0x00E39BC2 .. 0x00E39E41 (link.w A6,-0x50; D2-D7/A2-A4 saved; A5 is the
 * caller's &vtoc_$data, never reloaded).
 *
 * Frame:
 *   (0x08,A6)  block     indirect block address (also BAT_$FREE's array)
 *   (0x0C,A6)  level     word -> D5w; 1 = entries are data blocks
 *   (0x0E,A6)  base      longword, first logical block this block maps
 *   (0x12,A6)  step      longword -> D4, logical blocks per entry
 *   (0x16,A6)  whole     BOOLEAN byte: the whole block goes
 *   (0x18,A6)  status    pushed by every caller but never read here; the
 *                        body uses the enclosing (0x1A,A4) status instead
 *   (-0x10,A6) child_idx[1..5]   words, the entry index of each child
 *   (-0x28,A6) child_block[1..5] longwords, child block addresses
 *   (-0x30,A6) cur_base  first logical block of entry i
 *   (-0x38,A6) buf       this indirect block
 *   (-0x40,A6) i         entry index
 *   (-0x42,A6) dirty     BOOLEAN, entries cleared since the last write
 *   (-0x44,A6) remaining loop count (subq.w/bcc)
 *   (-0x4C,A6) p         &buf[i]
 *   (-0x50,A6) child_step  step >> 8
 *   D2w n (entries collected since the last flush), D6w level - 1
 */
static void vtoc_$free_indirect(vtoce_$truncate_frame_t *up, uint32_t block,
                                int16_t level, uint32_t base, uint32_t step,
                                boolean whole, status_$t *status_unused)
{
    int16_t n;                      /* D2w */
    boolean dirty;                  /* (-0x42,A6) */
    uint32_t *buf;                  /* (-0x38,A6) */
    int16_t start;                  /* D1w */
    uint32_t cur_base;              /* (-0x30,A6) */
    int16_t remaining;              /* (-0x44,A6) */
    int16_t i;                      /* (-0x40,A6) */
    int16_t child_level;            /* D6w */
    uint32_t child_step;            /* (-0x50,A6) */
    uint32_t *p;                    /* (-0x4C,A6) */
    uint32_t entry;                 /* D0 */
    uint32_t child_block[5];        /* (-0x28,A6), Pascal [1..5] */
    int16_t child_idx[5];           /* (-0x10,A6), Pascal [1..5] */
    uint32_t child_base;            /* D2 in the recursion loop */
    int16_t j;                      /* D3w dbf counter */

    (void)status_unused;

    /* 0x00E39BCA .. 0x00E39BD6 */
    n = 0;
    dirty = 0;

    /* 0x00E39BDA .. 0x00E39C02: fetch this indirect block under the
     * object's UID, hint = base, type = level, flags = D2w (0) */
    buf = (uint32_t *)DBUF_$GET_BLOCK(up->vol_idx, (int32_t)block,
                                      &up->loc->uid, base, (uint16_t)level,
                                      (uint16_t)n, up->status);
    /* 0x00E39C06 .. 0x00E39C0C: an error returns without a release */
    if (*up->status != status_$ok) {
        return;
    }

    /* 0x00E39C10 .. 0x00E39C2E: first entry to visit */
    if (whole < 0) {
        start = n;                                      /* 0x00E39C16 */
    } else {
        start = (int16_t)M$DIS$LLL((long)(int32_t)(up->new_blocks - base),
                                   (long)(int32_t)step);
    }

    /* 0x00E39C30 .. 0x00E39C42: cur_base = start * step + base */
    cur_base = (uint32_t)M$MIS$LLW((long)(int32_t)step, start) + base;

    /* 0x00E39C46 .. 0x00E39C4C: for i := start to 0xFF */
    remaining = (int16_t)(uint16_t)(0xFF - (uint16_t)start);
    if (remaining >= 0) {
        /* 0x00E39C50 .. 0x00E39C74 */
        i = start;
        child_level = (int16_t)(level - 1);
        child_step = step >> 8;
        p = &buf[i];

        do {
            /* 0x00E39C78 .. 0x00E39C7E */
            entry = *p;
            if (entry != 0) {
                /* 0x00E39C80 */
                n++;
                if (level == 1) {
                    /* 0x00E39C88 .. 0x00E39C98: (0x284,A5,n*4) */
                    vtoc_$data.free_list[n - 1] = entry & 0x7FFFFFFF;
                } else {
                    /* 0x00E39C9E .. 0x00E39CB4 */
                    child_block[n - 1] = entry & 0x7FFFFFFF;
                    child_idx[n - 1] = i;
                }
                /* 0x00E39CBA .. 0x00E39CCC: a partial block loses the
                 * entries that start at or beyond the new end */
                if (whole >= 0 && !(up->new_blocks > cur_base)) {
                    *p = 0;
                    dirty = (boolean)-1;
                }
            }

            /* 0x00E39CD0 .. 0x00E39CEC: flush at five children (levels
             * above 1) or at the last entry with anything collected */
            if ((n >= 5 && level > 1) || (i == 0xFF && n > 0)) {
                /* 0x00E39CF0 .. 0x00E39D1A: write the cleared entries
                 * back, keeping the buffer */
                if (dirty < 0) {
                    DBUF_$SET_BUFF(buf, DBUF_FLAG_DIRTY | DBUF_FLAG_WRITEBACK,
                                   up->status);
                    dirty = 0;
                    if (*up->status != status_$ok) {
                        goto release;
                    }
                }

                if (level == 1) {
                    /* 0x00E39D24 .. 0x00E39D58: the count is added even
                     * when BAT_$FREE fails */
                    BAT_$FREE(vtoc_$data.free_list, n, (int16_t)up->vol_idx,
                              0, up->status);
                    *up->blocks_freed += (uint32_t)(int32_t)n;
                    if (*up->status != status_$ok) {
                        goto release;
                    }
                } else {
                    /* 0x00E39D5A .. 0x00E39DAE: recurse into each child;
                     * it goes whole when it starts at or beyond the end
                     * (`scc`, unsigned).  D3w = n-1 with dbf = n passes,
                     * none when n-1 < 0 (bmi at 0x00E39D5E). */
                    for (j = 0; j < n; j++) {
                        child_base = (uint32_t)M$MIS$LLW((long)(int32_t)step,
                                                         child_idx[j]) + base;
                        vtoc_$free_indirect(up, child_block[j], child_level,
                                            child_base, child_step,
                                            (child_base >= up->new_blocks)
                                                ? (boolean)-1 : 0,
                                            up->status);
                        if (*up->status != status_$ok) {
                            goto release;
                        }
                    }
                }
                /* 0x00E39DB2 */
                n = 0;
            }

            /* 0x00E39DB4 .. 0x00E39DC4 */
            cur_base += step;
            i++;
            p++;
        } while (remaining-- != 0);
    }

    /* 0x00E39DC8 .. 0x00E39E22: a whole block frees itself (its address
     * as passed, flag bit and all) and is released with 0xC */
    if (whole < 0) {
        BAT_$FREE(&block, 1, (int16_t)up->vol_idx, 0, up->status);
        *up->blocks_freed = *up->blocks_freed + 1;
        DBUF_$SET_BUFF(buf, DBUF_FLAG_INVALIDATE | DBUF_FLAG_RELEASE,
                       &up->scratch);
        if (*up->status == status_$ok) {
            *up->status = up->scratch;
        }
        return;
    }

release:
    /* 0x00E39E24 .. 0x00E39E36 */
    DBUF_$SET_BUFF(buf, BAT_BUF_CLEAN, &up->scratch);
}

void VTOCE_$TRUNCATE(vtoc_$lookup_req_t *loc, uint32_t size,
                     int32_t alloc_length, boolean delete_it,
                     uint32_t *blocks_freed, status_$t *status)
{
    vtoce_$truncate_frame_t up;
    int32_t len;                    /* D1 */
    uint32_t vtoce_block;           /* (-0x2C,A6) */
    uint16_t entry_idx;             /* D3w */
    int8_t fmt;                     /* D4b */
    int16_t freed;                  /* (-0x40,A6) */
    boolean changed;                /* (-0x4A,A6) */
    boolean found;                  /* (-0x48,A6) */
    void *bkt_buf;                  /* (-0x20,A6) */
    uint16_t bkt_idx;               /* (-0x3C,A6) */
    uint32_t bkt_block;             /* (-0x30,A6) / D2 */
    vtoc_$bucket_entry_t *bkt;      /* A1 */
    int16_t s;                      /* D1w */
    int16_t k;                      /* D0w dbf counter */
    int16_t slot;                   /* D7w; only read with bkt_buf held,
                                     * which implies it was set */
    uint8_t *blk;                   /* A2 */
    vtoce_$hdr_t *hdr;              /* A0 */
    uint32_t *roots;                /* A1 */
    uint32_t *direct;               /* (-0x08,A6) */
    uint32_t root1, root2, root3;   /* D2, D5, D6 */
    uint16_t i;                     /* (-0x3E,A6) / D1 */
    int16_t cnt;                    /* D3w dbf counter */
    uint16_t cache_flags;           /* (-0x38,A6) */
    uint32_t cache_info;            /* (-0x04,A6) */

    (void)size;
    slot = 0;

    up.loc = loc;
    up.blocks_freed = blocks_freed;
    up.status = status;

    /* 0x00E39E50 .. 0x00E39E5E */
    up.vol_idx = loc->vol_idx;

    /* 0x00E39E62 .. 0x00E39E74: round up to 1K blocks; the second add
     * makes the arithmetic shift truncate toward zero */
    len = (int32_t)((uint32_t)alloc_length + 0x3FF);
    if (len < 0) {
        len = (int32_t)((uint32_t)len + 0x3FF);
    }
    up.new_blocks = (uint32_t)(len >> 10);

    /* 0x00E39E78 .. 0x00E39E8C */
    vtoce_block = loc->block_hint >> 4;
    entry_idx = (uint16_t)(loc->block_hint & 0x0F);

    /* 0x00E39E90 .. 0x00E39EAA */
    *blocks_freed = 0;
    freed = 0;
    fmt = vtoc_$data.format[up.vol_idx];
    changed = 0;
    bkt_buf = NULL;

    /* 0x00E39EAE .. 0x00E39EBA */
    ML_$LOCK(VTOC_LOCK_ID);

    /* 0x00E39EBC .. 0x00E39ED4 */
    if (vtoc_$data.mounted[up.vol_idx] >= 0) {
        *status = status_$VTOC_not_mounted;
        goto done;
    }

    /* 0x00E39ED8 .. 0x00E39EDE: new format AND delete */
    if ((int8_t)(fmt & delete_it) < 0) {
        /* 0x00E39EE2 .. 0x00E39F12 */
        found = 0;
        vtoc_$hash_uid(&loc->uid, (short)up.vol_idx, &bkt_idx, &bkt_block,
                       status);
        if (*status != status_$ok) {
            goto done;
        }

        do {
            /* 0x00E39F1C .. 0x00E39F44: the buffer pointer is stored
             * before the status test */
            bkt_buf = DBUF_$GET_BLOCK(up.vol_idx, (int32_t)bkt_block,
                                      &VTOC_BKT_$UID, bkt_block, 0, 0, status);
            if (*status != status_$ok) {
                goto done;
            }

            /* 0x00E39F48 .. 0x00E39F8E: twenty slots */
            bkt = (vtoc_$bucket_entry_t *)((uint8_t *)bkt_buf +
                                           (int32_t)(int16_t)bkt_idx *
                                               VTOC_BUCKET_ENTRY_SIZE);
            k = 0x13;
            s = 0;
            do {
                if (bkt->slots[s].block_info != 0 &&
                    bkt->slots[s].uid.high == loc->uid.high &&
                    bkt->slots[s].uid.low == loc->uid.low) {
                    found = (boolean)-1;                /* 0x00E39F80 */
                    slot = s;
                    break;
                }
                s++;
            } while (--k != -1);

            /* 0x00E39F92 */
            if (found < 0) {
                goto have_slot;
            }

            /* 0x00E39F98 .. 0x00E39FBA: next bucket in the chain */
            bkt_block = bkt->next_bucket;
            bkt_idx = bkt->next_bkt_idx;
            DBUF_$SET_BUFF(bkt_buf, BAT_BUF_CLEAN, &up.scratch);
        } while (bkt_block != 0);

        /* 0x00E39FBE .. 0x00E39FCC: 0x20006 "UID not found" */
        bkt_buf = NULL;
        *status = status_$VTOC_invalid_vtoce;
        goto done;
    }

have_slot:
    /* 0x00E39FD0 .. 0x00E39FFC */
    blk = (uint8_t *)DBUF_$GET_BLOCK(up.vol_idx, (int32_t)vtoce_block,
                                     &VTOC_$UID, vtoce_block, 0, 0, status);
    if (*status != status_$ok) {
        goto done;
    }

    if (fmt < 0) {
        /* 0x00E3A004 .. 0x00E3A044: the entry must be in use and carry
         * the UID.  Otherwise 0x80020002 ("VTOC is bad") - and the VTOCE
         * block is never released: the exit only releases bkt_buf. */
        hdr = (vtoce_$hdr_t *)(blk + offsetof(vtoc_$vtoce_block_t, entries) +
                               (int32_t)(int16_t)entry_idx * VTOCE_NEW_SIZE);
        if (!(hdr->status < 0) ||
            hdr->uid.high != loc->uid.high || hdr->uid.low != loc->uid.low) {
            *status = status_$VTOC_uid_mismatch;
            goto done;
        }
        roots = ((vtoce_$new_fm_t *)hdr)->indirect;
        direct = ((vtoce_$new_fm_t *)hdr)->direct;
    } else {
        /* 0x00E3A046 .. 0x00E3A058: no in-use or UID check */
        hdr = (vtoce_$hdr_t *)(blk + offsetof(vtoc_$old_block_t, entries) +
                               (int32_t)(int16_t)entry_idx * VTOCE_OLD_SIZE);
        roots = ((vtoce_$old_fm_t *)hdr)->indirect;
        direct = ((vtoce_$old_fm_t *)hdr)->direct;
    }

    /* 0x00E3A05C .. 0x00E3A064 */
    root3 = roots[2];
    root2 = roots[1];
    root1 = roots[0];

    if (delete_it < 0) {
        /* 0x00E3A06C */
        changed = (boolean)-1;
        if (fmt < 0) {
            /* 0x00E3A074 .. 0x00E3A0A6: bclr.b #0xf = bit 7 of the high
             * byte = bit 15 of the status word */
            hdr->status = (int16_t)((uint16_t)hdr->status & 0x7FFF);
            ((vtoc_$vtoce_block_t *)blk)->entry_count--;
            if (((vtoc_$vtoce_block_t *)blk)->entry_count == 2) {
                ((vtoc_$vtoce_block_t *)blk)->next_block =
                    BAT_$ADD_PART_VTOCE((int16_t)up.vol_idx, vtoce_block,
                                        status);
            }
        } else {
            /* 0x00E3A0A8 .. 0x00E3A0AE */
            hdr->status = (int16_t)((uint16_t)hdr->status & 0x7FFF);
        }
        /* 0x00E3A0B4 .. 0x00E3A0CC: drop the UID-cache entry */
        (void)vtoc_$uid_cache_lookup(&loc->uid, &cache_flags, &cache_info,
                                     (char)0xFF);
    } else {
        /* 0x00E3A0D2 .. 0x00E3A10E: unsigned compares (bhi) */
        if (up.new_blocks <= FM_LEVEL1_MAX && root1 != 0) {
            changed = (boolean)-1;
            roots[0] = 0;
        }
        if (up.new_blocks <= FM_LEVEL2_MAX && root2 != 0) {
            changed = (boolean)-1;
            roots[1] = 0;
        }
        if (up.new_blocks <= FM_LEVEL3_MAX && root3 != 0) {
            changed = (boolean)-1;
            roots[2] = 0;
        }
    }

    /* 0x00E3A112 .. 0x00E3A170: direct blocks new_blocks .. 0x1F */
    if (up.new_blocks < FM_LEVEL1_MAX) {
        if (!((uint16_t)up.new_blocks > 0x1F)) {
            cnt = (int16_t)(0x1F - (uint16_t)up.new_blocks);
            i = (uint16_t)up.new_blocks;
            do {
                if (direct[i] != 0) {
                    freed++;
                    /* (0x284,A1) with A1 = A5 + freed*4 */
                    vtoc_$data.free_list[freed - 1] = direct[i] & 0x7FFFFFFF;
                    direct[i] = 0;
                }
                i++;
            } while (--cnt != -1);
        }
        if (freed > 0) {
            changed = (boolean)-1;
        }
    }

    if (changed < 0) {
        /* 0x00E3A17C .. 0x00E3A198 */
        DBUF_$SET_BUFF(blk, BAT_BUF_WRITEBACK, status);
        if (*status == status_$ok) {
            /* 0x00E3A19C .. 0x00E3A1BA: status not tested after */
            if (freed != 0) {
                BAT_$FREE(vtoc_$data.free_list, freed, (int16_t)up.vol_idx,
                          0, status);
            }
            /* 0x00E3A1BE .. 0x00E3A202: empty the bucket slot */
            if (bkt_buf != NULL) {
                bkt = (vtoc_$bucket_entry_t *)((uint8_t *)bkt_buf +
                                               (int32_t)(int16_t)bkt_idx *
                                                   VTOC_BUCKET_ENTRY_SIZE);
                bkt->slots[slot].block_info = 0;
                DBUF_$SET_BUFF(bkt_buf, BAT_BUF_DIRTY, status);
                bkt_buf = NULL;
            }
        }
    } else {
        /* 0x00E3A208 .. 0x00E3A21A */
        DBUF_$SET_BUFF(blk, BAT_BUF_DIRTY, status);
    }

    /* 0x00E3A21E .. 0x00E3A232 */
    if (*status != status_$ok) {
        goto done;
    }
    *blocks_freed = (uint32_t)(int32_t)freed;

    /* 0x00E3A234 .. 0x00E3A270: level 1, entries 0x20 .. 0x11F */
    if (root1 != 0 && up.new_blocks < FM_LEVEL2_MAX) {
        vtoc_$free_indirect(&up, root1, 1, FM_LEVEL1_MAX, 1,
                            (up.new_blocks <= FM_LEVEL1_MAX) ? (boolean)-1 : 0,
                            status);
        if (*status != status_$ok) {
            goto done;
        }
    }

    /* 0x00E3A272 .. 0x00E3A2AE: level 2, entries 0x120 .. 0x1011F */
    if (root2 != 0 && up.new_blocks < FM_LEVEL3_MAX) {
        vtoc_$free_indirect(&up, root2, 2, FM_LEVEL2_MAX, 0x100,
                            (up.new_blocks <= FM_LEVEL2_MAX) ? (boolean)-1 : 0,
                            status);
        if (*status != status_$ok) {
            goto done;
        }
    }

    /* 0x00E3A2B0 .. 0x00E3A2DC: level 3, from 0x10120, no range test */
    if (root3 != 0) {
        vtoc_$free_indirect(&up, root3, 3, FM_LEVEL3_MAX, 0x10000,
                            (up.new_blocks <= FM_LEVEL3_MAX) ? (boolean)-1 : 0,
                            status);
    }

done:
    /* 0x00E3A2E0 .. 0x00E3A2FA */
    if (bkt_buf != NULL) {
        DBUF_$SET_BUFF(bkt_buf, BAT_BUF_CLEAN, &up.scratch);
    }
    /* 0x00E3A2FE .. 0x00E3A304 */
    ML_$UNLOCK(VTOC_LOCK_ID);
}
